Suppose that a function $\psi : \mathbb{N} \to (0, \infty)$ satisfies the following two conditions: 

\begin{itemize}
\item[(I)] there exists $c >0$ such that for all $n \ge 1$ and $k \in [n, 2n]$ 
$$\psi (k) = \psi (n) \big\{ 1 + O \big( (\log n)^{-c} \big) \big\}.$$

\item[(II)] there exists $\epsilon > 0$ such that for all $n \ge 1$ 
$$ \psi (2n) = \psi (n) \Big\{ 1 - \frac{\log 2 }{2 \log n} + O \big( (\log n)^{-1 - \epsilon} \big) \Big\}.$$ 

\end{itemize}
Set $\delta = \min \{ c, \epsilon \}$. Then there exists $a > 0$ such that 
$$\psi (n) = a  (\log n)^{-\frac{1}{2}} \Big\{ 1 + O \Big( \big( \log n \big)^{-\delta} \Big) \Big\},$$

\end{lemma}

