ref_dict.cor:cn-choice:
\begin{corollary}\label{cor:cn-choice}
Let $\theta:=\alpha\beta-d$ if $0<\beta<1$ and $\theta:=\alpha-d$ if $\beta\ge 1$. Define $c_n$ by
\[
c_n:=
\begin{cases}
\Bigl(2^d\omega_d\,\Gamma(1-\beta)\lambda^\beta\,\beta\,\dfrac{d}{\alpha\beta-d}\cdot \dfrac{\alpha d}{\theta}\Bigr)^{1/\theta}
\,n^{d/\theta}(\log n)^{1/\theta},
& 0<\beta<1,\\[2mm]
\Bigl(2^d\omega_d\,\dfrac12\lambda\,\dfrac{d}{\alpha-d}\cdot \dfrac{\alpha^2 d^2}{\theta^2}\Bigr)^{1/\theta}
\,n^{d/\theta}(\log n)^{2/\theta},
& \beta=1,\\[2mm]
\Bigl(2^d\omega_d\,\lambda\,\dfrac{\beta^2}{(\beta-1)^2}\,\dfrac{d}{\alpha-d}\Bigr)^{1/\theta}
\,n^{d/\theta},
& \beta>1,
\end{cases}
\]
and set $r_n=c_n r$ for fixed $r>0$. Then
\[
I_1 \sim r^{-\theta},
\qquad n\to\infty.
\]
\end{corollary}

ref_dict.proofthm2:
\begin{proof}
By Corollary~\ref{cor:cn-choice}, $I_1\to r^{-\theta}$. It remains to show that $I_2=0$ for $n$ large. Under the stated
assumptions on $\theta$, the scaling $r_n=c_n r$ satisfies $r_n/n\to\infty$, hence $r_n\ge 2n$ for all sufficiently large $n$.
For such $n$ and any $x\in B_n$, we have $B_n\subset B_{r_n}(x)$, equivalently $B_n\cap B_{r_n}^C(x)=\varnothing$, so there
are no exceedance pairs entirely contained in $B_n$. Thus $I_2=0$ for all large $n$, and the limit follows.
\end{proof}

Finally the proof of Theorem \ref{thm:uncond-max} follows from Proposition \ref{prop:Poisson-approx-Fnr} combined with Theorem \ref{thm:mean-exceedances-limit}. 

\section{Proof of Theorem \ref{thm:POT-hub}}\label{proofthm2}

Recall that we denote $W_n^*=\max_{x\in V\cap B_n}W_x$. We start this section with the following observation.

\begin{lemma}\label{le:TailW*n}
It holds
\[\mathbb{P}_0\left(W_n^*\leq d_n\right)=\left(1-d_n^{-\beta}\right)\exp\left(-(2n)^dd_n^{-\beta}\right)\sim\left(1-d_n^{-\beta}\right)^{(2n)^d+1}\]
\end{lemma}
\begin{proof}
We have
\begin{align*}
\mathbb{P}_0\left(W_n^*\leq d_n\right)&=\sum_{k=0}^\infty\mathbb{P}_0\left(W_n^*\leq d_n\vert \# \left(V\cap B_n\setminus\{0\}\right)=k\right)\mathbb{P}_0\left(\#\left(V\cap B_n\setminus\{0\}\right)=k\right)\\
&=\sum_{k=0}^\infty\mathbb{P}_0\left(W_0\leq d_n\right)^{k+1}\mathbb{P}_0\left(\#\left(V\cap B_n\setminus\{0\}\right)=k\right)\\
&=(1-d_n^{-\beta})\sum_{k=0}^\infty(1-d_n^{-\beta})^{k}\mathbb{P}_0\left(\#\left(V\cap B_n\setminus\{0\}\right)=k\right)\\
&=(1-d_n^{-\beta})\exp\left(-(2n)^dd_n^{-\beta}\right)
\end{align*}
since $\#\left(V\cap B_n\setminus\{0\}\right)$ is Poisson distributed with mean $(2n)^d$. The second claim follows from the classical approximation $\ln(1-d_n^{-\beta})\sim -d_n^{-\beta}$ (since $d_n\nearrow\infty$).
\end{proof}

