\label{thm1}
Assume (F), \begin{equation}
\label{init1}
\liminf_{y\to-\infty}\inf_{x\in\mathbf{R}^{n-1}}u_{0}(x,y)>0 \\
\end{equation}
and \begin{equation}
\label{init3}
c=c_*>2\sqrt{f'(0)}, \qquad 
\limsup_{y\to\infty}\sup_{x\in\mathbf{R}^{n-1}} u_{0}(x,y)e^{-\lambda_1 y}<\infty \ \mbox{ for some } \ \lambda_1<\lambda_+,
\end{equation}
and let $u$ be a solution of \begin{aligned}\label{Rea-Diff}
&u_{t}=\Delta u+f(u), && x\in\mathbb{R}^{n-1}, \, y\in\mathbb{R}, \, t>0, \\
&u(x,y,0)=u_{0}(x,y), && x\in\mathbb{R}^{n-1}, \, y\in\mathbb{R}.
\end{aligned}
Then there exists a smooth function  $\gamma=\gamma(x,t)$ with the following properties.
\begin{enumerate}
\item[(i)] 
There exists $T>0$ such that 
\begin{equation*}
\{ (x,y,t) \in \mathbf{R}^{n-1} \times \mathbf{R} \times [T,\infty); \, u(x,y,t)=\Phi_c(0)\}=\{y=\gamma(x,t)\}.
\end{equation*}
Moreover, it holds that
\begin{equation*}
\lim_{t\rightarrow\infty}\sup_{(x,y)\in\mathbf{R}^n }|u(x,y,t)-\Phi_c(y-\gamma(x,t))|=0.
\end{equation*}
\item[(ii)]
For any $\varepsilon>0$, there exists $\tau_{\varepsilon}\in[T,\infty)$ such that the solution $U(x,t)$ of the problem
\begin{equation}\label{MCF}
\left\{
\begin{aligned}
&\frac{U_t}{\sqrt{1+|\nabla_x U|^2}}=\mathrm{div}\left(\frac{\nabla_x U}{\sqrt{1+|\nabla_x U|}}\right)+c_*,&&x\in\mathbf{R}^{n-1},t>0,\\
&U(x,0)=\gamma(x,\tau_{\varepsilon}),&&x\in\mathbf{R}^{n-1},
\end{aligned}
\right.
\end{equation}
satisfies
\begin{equation*}
\sup_{x\in\mathbf{R}^{n-1},t\ge\tau_{\varepsilon}}|\gamma(x,t)-U(x,t-\tau_{\varepsilon})|\le\varepsilon.
\end{equation*}
\end{enumerate}
Furthermore, the assertion (i) still holds if
\begin{gather}
\liminf_{y \to -\infty} \inf_{x \in \mathbb{R}^{n-1}} u_0(x,y)>1-\delta_0, \label{lbidni} \\
0<\liminf_{y\to\infty}\inf_{x\in\mathbf{R}^{n-1}} \frac{u_0(x,y)}{\Phi_c(y)}, \quad
\limsup_{y\to\infty}\sup_{x\in\mathbf{R}^{n-1}}\frac{u_0(x,y)}{\Phi_c(y)}<\infty 
\ \mbox{ for some } \ c \ge c_*, \label{init2}
\end{gather}
is assumed instead of the preceding assumption.

