expanded_theorem:
\label{thm}
	Let $s>0, \lambda>0, d=2,3$ and $T>0$. Then the data-to-solution map $(u_0,b_0)\mapsto(u,b)$ for the equations

\begin{align}\label{mhd}
	\begin{cases}
	\partial_t u+u \cdot \nabla u+\nabla p=b\cdot \nabla b,\\[1mm]
\partial_t b-\Delta b+u\cdot \nabla b=b\cdot\nabla u,  \\[1mm]
\text{div}\, u=\text{div}\, b=0, \\[1mm]
\nu(x, 0)=u_0(x),\,\, b(x, 0)=b_0(x),
	\end{cases}
\end{align}

	is non-uniformly continuous from a bounded subset in $H^{s}(\mathbb{R}^d)\times H^{s}(\mathbb{R}^d)$ into $C\left([0,T],H^{s}(\mathbb{R}^d)\right)\times C\left([0,T],H^{s}(\mathbb{R}^d)\right)$.

  More precisely, for any $\gamma>0$ and arbitrary constant magnetic field ${\bf B_0}\in \mathbb{R}^d$,  there exists two sequences of solutions $(u^{+1,\lambda},b^{+1,\lambda})$ and $(u^{-1,\lambda},b^{-1,\lambda})$ such that
	\begin{itemize}
		\item the solutions satisfy
\begin{align*}
			(u^{\pm 1,\lambda}, b^{\pm 1,\lambda} - {\bf B_0}) \in C([0,T], H^{s}(\mathbb{R}^{d})) \times C([0,T], H^{s}(\mathbb{R}^{d}));
\end{align*}
		\item  the initial data satisfy
\begin{equation}\label{nonuniform-initial-bound}
	\begin{array}{l}
						\|u^{+1,\lambda}(0,\cdot)\|_{H^{s}} + \|b^{+1,\lambda}(0,\cdot) - {\bf B_0}\|_{H^{s}} \leq \gamma, \\[2mm]
		\|u^{-1,\lambda}(0,\cdot)\|_{H^{s}} + \|b^{-1,\lambda}(0,\cdot) - {\bf B_0}\|_{H^{s}} \leq \gamma;
	\end{array}
\end{equation}
		\item and the non-uniform continuity is characterized by
		\begin{itemize}
			\item at initial time $t=0$,
			\begin{align}\label{nonuniform-initial-diff}
				\lim_{\lambda\to\infty} \|u^{+1,\lambda}(0,\cdot) - u^{-1,\lambda}(0,\cdot)\|_{H^{s}} = 0,
			\end{align}
			\item for evolution times $t>0$,
			\begin{align}\label{nonuniform-low-bound-sint}
				\lim_{\lambda \to\infty} \|u^{+1,\lambda}(t) - u^{-1,\lambda}(t)\|_{H^{s}} \geq c\gamma |\sin t|,
			\end{align}
		\end{itemize}
		where $c = c(s,d) > 0$ is a constant depending only on  $s$ and $d$.
	\end{itemize}

choices.text:
For any $\gamma>0$ and any constant ${\bf B}_0\in\mathbb{R}^d$, there exist two families of solutions $\{(u^{+1,\lambda},b^{+1,\lambda})\}_{\lambda}$ and $\{(u^{-1,\lambda},b^{-1,\lambda})\}_{\lambda}$ such that
1) $(u^{\pm1,\lambda},\, b^{\pm1,\lambda}-{\bf B}_0)\in C([0,T],H^s(\mathbb{R}^d))\times C([0,T],H^s(\mathbb{R}^d))$;
2) $\|u^{\pm1,\lambda}(0)\|_{H^s}+\|b^{\pm1,\lambda}(0)-{\bf B}_0\|_{H^s}\le \gamma$;
3) at $t=0$, $\lim_{\lambda\to\infty}\|u^{+1,\lambda}(0)-u^{-1,\lambda}(0)\|_{H^s}=0$.
(In particular, the data-to-solution map cannot be Lipschitz on bounded subsets of $H^s\times H^s$.)

