ref_dict.theorem:main:
\begin{thm}\label{theorem:main}
    Let $f$ be a cuspidal modular form of weight $k$ on $\SL_2(\BZ)$. For any integers $l\geq2$ and $d\geq1$ and $dl>4$, one has
    \[\sum_{n\leq x}  \lambda^l_{\Sym^d f}(n)=xP_{d,l}(\log x)+O\left(x^{\theta_{d,l}+\epsilon}\right).\]
    Here $P_{d,l}$ is a polynomial of degree $K_{0,d,l}-1$, where $K_{i,d,l}$ denote the Kostka number defined in sections \ref{section:Weylmod} and \ref{section:Kostka number}. The exponent $\theta_{d, l}$ is given by
    $$\theta_{d,l}=1-1/\left((d+1)^l/2-4K_{0,d,l}/21-K_{1,d,l}/3-5K_{2,d,l}/14\right).$$
\end{thm}

ref_dict.proposition:dirichletseriescomp:
\begin{prop}\label{proposition:dirichletseriescomp}
The following identities hold:
\begin{align*}
   &D\left(f^{\otimes l},s\right)=L\left(f^{\otimes l},s\right)U_{f,l}(s),D\left(\left(\Sym^d f\right)^{\otimes l},s\right)=L\left(\left(\Sym^df\right)^{\otimes l},s\right)U_{\Sym^d f,l}(s),\\ 
   &D\left(f^{\otimes l},\chi,s\right)=L\left(f^{\otimes l},\chi,s\right)U_{f,l,\chi}(s),D\left(\left(\Sym^d f\right)^{\otimes l},\chi,s\right)=L\left(\left(\Sym^df\right)^{\otimes l},\chi,s\right)U_{\Sym^d f,l,\chi}(s).
\end{align*}
       where each  $U_*(s)$ is an Euler product that is absolutely convergent for  $\Re(s)>1/2$ and uniformly convergent in the region $\Re(s)>1/2+\epsilon$ for any $\epsilon>0$.
\end{prop}

